        return []
    out = sorted(xs)
    out.insert(2, out[0] + out[-1])
    return out

def f(xs):
    if xs <= 0:
        return 0
    a, b = 0, 1
    for digit in bin(xs)[2:]:
        c = a * (2 * b - a)
        d = a * a + b * b
        a, b = (d, c + d) if digit == "1" else (c, d)
